<template>
  <div class="detection">
    <Header />
    <h2>疾病识别</h2>
    <Navigation />
    <div class="detection-tabs">
      <button @click="activeTab = 'single'" :class="{ active: activeTab === 'single' }">单人识别</button>
      <button @click="activeTab = 'multiple'" :class="{ active: activeTab === 'multiple' }">多人识别</button>
    </div>

    <!-- 单人识别模式 -->
    <div v-if="activeTab === 'single'" class="single-detection">
      <h3>单人识别</h3>
      <div class="patient-info-panel">
        <h4>患者信息</h4>
        <p>姓名：{{ patientInfo.name }}</p>
        <p>年龄：{{ patientInfo.age }}</p>
        <p>病史：{{ patientInfo.medicalHistory }}</p>
      </div>
      
      <form @submit.prevent="submitSingleDetection">
        <div class="form-group">
          <label for="single-image">上传眼底图像</label>
          <input type="file" id="single-image" @change="handleSingleImageChange" accept="image/*" required>
        </div>
        <button type="submit">识别</button>
      </form>
      
      <div v-if="singleResult" class="result-container">
        <div class="diagnosis-info">
          <h4>诊断结果</h4>
          <div class="diagnosis-details">
            <p>疾病名称：{{ singleResult.diseaseName }}</p>
            <p>分期：{{ singleResult.stage }}</p>
            <p>置信度：{{ singleResult.confidence }}%</p>
            <p>风险等级：<span :class="`risk-level risk-${singleResult.riskLevel}`">{{ singleResult.riskLevel }}</span></p>
          </div>
        </div>
        
        <div class="lesion-annotation">
          <h4>病变区域标注</h4>
          <div class="annotation-image">
            <!-- 这里展示标注后的图像 -->
            <canvas id="annotationCanvas" width="800" height="600"></canvas>
            <div class="annotation-tools">
              <button @click="showHeatmap">热力图</button>
              <button @click="showContour">轮廓线</button>
              <button @click="showMagnified">局部放大</button>
            </div>
          </div>
        </div>
        
        <div class="multimodal-data">
          <h4>多模态数据融合</h4>
          <div class="data-fusion">
            <p>OCT结果：{{ singleResult.octResult }}</p>
            <p>视野检查结果：{{ singleResult.perimetryResult }}</p>
          </div>
        </div>
        
        <div class="historical-comparison">
          <h4>历史影像对比</h4>
          <div class="comparison-timeline">
            <div v-for="(history, index) in singleResult.historicalImages" :key="index" class="timeline-item">
              <span>{{ history.date }}</span>
              <img :src="history.image" alt="历史影像">
              <p>病变面积：{{ history.lesionArea }}%</p>
            </div>
          </div>
        </div>
        
        <div class="clinical-tools">
          <h4>临床工具</h4>
          <div class="tools-panel">
            <button @click="toggleMeasurement">标尺测量</button>
            <button @click="toggleAreaCalculation">面积计算</button>
            <button @click="toggleImageEnhancement">影像增强</button>
            <button @click="toggleLayers">图层管理</button>
          </div>
        </div>
        
        <div class="generate-report">
          <button @click="generateSingleReport">一键生成报告</button>
        </div>
      </div>
    </div>
    
    <!-- 多人识别模式 -->
    <div v-if="activeTab === 'multiple'" class="multiple-detection">
      <h3>多人识别</h3>
      <form @submit.prevent="submitMultipleDetection">
        <div class="form-group">
          <label for="multiple-images">上传眼底图像（多选）</label>
          <input type="file" id="multiple-images" @change="handleMultipleImageChange" multiple accept="image/*" required>
        </div>
        <button type="submit">识别</button>
      </form>
      
      <div v-if="multipleResults.length > 0" class="results-container">
        <div class="batch-upload">
          <div class="upload-status">
            <span>已上传：{{ multipleResults.length }}张</span>
            <span>高风险：{{ highRiskCount }}张</span>
          </div>
          <div class="progress-bar">
            <div class="progress" :style="{ width: `${progressPercentage}%` }"></div>
          </div>
        </div>
        
        <div class="thumbnail-list">
          <div v-for="(result, index) in multipleResults" :key="index" class="thumbnail-item">
            <img :src="result.thumbnail" alt="缩略图">
            <div class="thumbnail-info">
              <p>姓名：{{ result.patientName }}</p>
              <p>疾病：{{ result.diseaseName }}</p>
              <p>风险等级：<span :class="`risk-level risk-${result.riskLevel}`">{{ result.riskLevel }}</span></p>
              <p>异常指标：{{ result.abnormalIndicators }}</p>
            </div>
          </div>
        </div>
        
        <div class="risk-dashboard">
          <h4>风险等级统计</h4>
          <div class="dashboard-stats">
            <div class="stat-item">
              <span class="stat-label">高风险</span>
              <span class="stat-value">{{ highRiskCount }}</span>
            </div>
            <div class="stat-item">
              <span class="stat-label">中风险</span>
              <span class="stat-value">{{ mediumRiskCount }}</span>
            </div>
            <div class="stat-item">
              <span class="stat-label">低风险</span>
              <span class="stat-value">{{ lowRiskCount }}</span>
            </div>
          </div>
        </div>
        
        <div class="batch-actions">
          <button @click="exportExcel">导出Excel</button>
          <button @click="exportPDF">导出PDF</button>
          <button @click="generateReferralSuggestions">生成转诊建议</button>
        </div>
      </div>
    </div>
    
    <Footer />
  </div>
</template>

<script>
import axios from 'axios';

export default {
  name: 'DetectionView',
  data() {
    return {
      activeTab: 'single',
      singleImage: null,
      multipleImages: [],
      singleResult: null,
      multipleResults: [],
      patientInfo: {
        name: '张三',
        age: '45岁',
        medicalHistory: '糖尿病史5年'
      },
      annotationImage: '', // 标注后的图像
      highRiskCount: 0,
      mediumRiskCount: 0,
      lowRiskCount: 0,
      progressPercentage: 0
    };
  },
  methods: {
    handleSingleImageChange(event) {
      this.singleImage = event.target.files[0];
    },
    handleMultipleImageChange(event) {
      this.multipleImages = Array.from(event.target.files);
    },
    // async submitSingleDetection() {
    //   if (!this.singleImage) return;

    //   const formData = new FormData();
    //   formData.append('left_image', this.singleImage);

    //   try {
    //     const response = await axios.post('http://localhost:5000/disease_prediction', formData, {
    //       headers: {
    //         'Content-Type': 'multipart/form-data'
    //       }
    //     });

    //     this.singleResult = response.data[0]; // 假设返回的结果是一个数组，取第一个元素
    //   } catch (error) {
    //     console.error('预测失败:', error);
    //     alert('预测失败，请重试');
    //   }
    // },
    async submitSingleDetection() {
  if (!this.singleImage) return;

  const formData = new FormData();
  formData.append('left_image', this.singleImage);

  try {
    const response = await axios.post('http://localhost:3000/disease_prediction', formData, {
      headers: {
        'Content-Type': 'multipart/form-data'
      }
    });

    // 打印响应数据，检查其结构和内容
    console.log('Response data:', response.data);

    // 确保响应数据格式正确
    if (Array.isArray(response.data) && response.data.length > 0) {
      this.singleResult = response.data[0];
    } else {
      throw new Error('响应数据格式不正确');
    }
  } catch (error) {
    console.error('预测失败:', error);
    if (error.response) {
      console.error('响应数据:', error.response.data);
    }
    alert('预测失败，请重试');
  }
},
    async submitMultipleDetection() {
      if (this.multipleImages.length === 0) return;

      const formData = new FormData();
      this.multipleImages.forEach((image, index) => {
        formData.append(`image_${index}`, image);
      });

      try {
        const response = await axios.post('http://localhost:3000/disease_prediction', formData, {
          headers: {
            'Content-Type': 'multipart/form-data'
          }
        });

        this.multipleResults = response.data;
      } catch (error) {
        console.error('批量预测失败:', error);
        alert('批量预测失败，请重试');
      }
    },
    showHeatmap() {
      const canvas = document.getElementById('annotationCanvas');
      const ctx = canvas.getContext('2d');
      
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      
      const heatmapData = [
        { x: 100, y: 200, value: 0.8 },
        { x: 300, y: 400, value: 0.6 },
        { x: 500, y: 600, value: 0.9 }
      ];

      heatmapData.forEach(point => {
        const radius = 10;
        ctx.beginPath();
        ctx.arc(point.x, point.y, radius, 0, 2 * Math.PI);
        ctx.fillStyle = `rgba(255, 0, 0, ${point.value})`;
        ctx.fill();
      });
    },
    showContour() {
      const canvas = document.getElementById('annotationCanvas');
      const ctx = canvas.getContext('2d');
      
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      
      const contourData = [
        { x: 100, y: 200 },
        { x: 300, y: 400 },
        { x: 500, y: 600 },
        { x: 700, y: 400 }
      ];

      ctx.beginPath();
      ctx.moveTo(contourData[0].x, contourData[0].y);
      for (let i = 1; i < contourData.length; i++) {
        ctx.lineTo(contourData[i].x, contourData[i].y);
      }
      ctx.closePath();
      ctx.strokeStyle = 'red';
      ctx.lineWidth = 2;
      ctx.stroke();
    },
    showMagnified() {
      const canvas = document.getElementById('annotationCanvas');
      const ctx = canvas.getContext('2d');
      
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      
      const magnifiedImage = document.createElement('img');
      magnifiedImage.src = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=';
      magnifiedImage.onload = function() {
        ctx.drawImage(magnifiedImage, 200, 300, 200, 200, 400, 600, 100, 100);
      };
    },
    toggleMeasurement() {
      const canvas = document.getElementById('annotationCanvas');
      const ctx = canvas.getContext('2d');
      
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      
      ctx.beginPath();
      ctx.moveTo(200, 300);
      ctx.lineTo(400, 300);
      ctx.strokeStyle = 'blue';
      ctx.lineWidth = 2;
      ctx.stroke();
      
      const distance = Math.sqrt(Math.pow(400 - 200, 2) + Math.pow(300 - 300, 2));
      console.log(`测量距离: ${distance}px`);
    },
    toggleAreaCalculation() {
      const canvas = document.getElementById('annotationCanvas');
      const ctx = canvas.getContext('2d');
      
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      
      ctx.beginPath();
      ctx.moveTo(200, 300);
      ctx.lineTo(400, 300);
      ctx.lineTo(400, 500);
      ctx.lineTo(200, 500);
      ctx.closePath();
      ctx.strokeStyle = 'green';
      ctx.lineWidth = 2;
      ctx.stroke();
      
      const width = 400 - 200;
      const height = 500 - 300;
      const area = width * height;
      console.log(`计算面积: ${area}px²`);
    },
    toggleImageEnhancement() {
      const canvas = document.getElementById('annotationCanvas');
      const ctx = canvas.getContext('2d');
      const img = new Image();
      img.src = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=';
      
      img.onload = function() {
        ctx.filter = 'brightness(1.5) contrast(1.2)';
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      };
    },
    toggleLayers() {
      const canvas = document.getElementById('annotationCanvas');
      const ctx = canvas.getContext('2d');
      
      if (ctx.filter === 'brightness(1.5) contrast(1.2)') {
        ctx.filter = 'none';
      } else {
        ctx.filter = 'brightness(1.5) contrast(1.2)';
      }
    },
    generateSingleReport() {
      console.log('生成单人报告');
    },
    exportExcel() {
      console.log('导出Excel');
    },
    exportPDF() {
      console.log('导出PDF');
    },
    generateReferralSuggestions() {
      console.log('生成转诊建议');
    }
  }
};
</script>

<style scoped>
@import '@/assets/css/global.css';
@import '@/assets/css/header.css';
@import '@/assets/css/detection.css';
</style>